SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsSignInResponse
{
    boolean success;
    str     errorCode;
    str     message;
    str     userName;
    str     displayName;
    HcmPersonnelNumberId personnelNumber;
    boolean isSupervisor;
    boolean isCycleCountSupervisor;
    real    maxOverPercent;
    real    maxOverQty;
    boolean mustChangePassword;
    List    warehouses;
    str     licenseWarning;
    List    modulePermissions;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

/// <summary>
/// INVALID_CREDENTIALS, INACTIVE, LOCKED_OUT, NO_WAREHOUSE, INVALID_REQUEST, NO_LICENSE,
/// LICENSE_INVALID, LICENSE_EXPIRED, DEVICE_LIMIT_REACHED.
///
/// A wrong user name and a wrong password both return INVALID_CREDENTIALS, deliberately.
/// Distinguishing them tells an attacker which user names exist, which is the first half of
/// the problem solved for them.
///
/// The four license-related codes are checked before any of the others - see
/// HSMobileOpsUserService::signIn - so a licensing problem is never mistaken for a wrong
/// password, and vice versa.
/// </summary>
[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('UserName')]
public str parmUserName(str _value = userName)
{
    userName = _value;
    return userName;
}

[DataMemberAttribute('DisplayName')]
public str parmDisplayName(str _value = displayName)
{
    displayName = _value;
    return displayName;
}

/// <summary>
/// The HcmWorker this login belongs to. This is what makes a posted receipt attributable to a
/// person, rather than to the service principal every device shares.
/// </summary>
[DataMemberAttribute('PersonnelNumber')]
public HcmPersonnelNumberId parmPersonnelNumber(HcmPersonnelNumberId _value = personnelNumber)
{
    personnelNumber = _value;
    return personnelNumber;
}

[DataMemberAttribute('IsSupervisor')]
public boolean parmIsSupervisor(boolean _value = isSupervisor)
{
    isSupervisor = _value;
    return isSupervisor;
}

/// <summary>
/// A distinct, narrower flag from IsSupervisor - a worker can review a count variance
/// without holding every other supervisor permission this app might grow, and vice versa.
/// Not yet acted on anywhere: the inventory count module itself is still planned, not
/// built. This exists now so that module can gate on it from day one instead of every
/// worker record needing a second migration to add it later.
/// </summary>
[DataMemberAttribute('IsCycleCountSupervisor')]
public boolean parmIsCycleCountSupervisor(boolean _value = isCycleCountSupervisor)
{
    isCycleCountSupervisor = _value;
    return isCycleCountSupervisor;
}

/// <summary>
/// This worker's personal over-delivery allowance, as a percentage of ordered quantity.
/// Zero means "no personal override" - not "this worker may never over-deliver", which
/// would make an unconfigured value silently more restrictive than a line with no
/// tolerance of its own already is. Only ever widens what a purchase order line's own
/// D365FO-configured tolerance already allows, never narrows it - see
/// ReceivingFlowViewModel.effectiveMaximum, the one place this is actually used.
/// </summary>
[DataMemberAttribute('MaxOverPercent')]
public real parmMaxOverPercent(real _value = maxOverPercent)
{
    maxOverPercent = _value;
    return maxOverPercent;
}

/// <summary>
/// This worker's personal over-delivery allowance, as an absolute quantity above ordered.
/// See parmMaxOverPercent - the same "zero means unconfigured, only ever widens" rule.
/// </summary>
[DataMemberAttribute('MaxOverQty')]
public real parmMaxOverQty(real _value = maxOverQty)
{
    maxOverQty = _value;
    return maxOverQty;
}

[DataMemberAttribute('MustChangePassword')]
public boolean parmMustChangePassword(boolean _value = mustChangePassword)
{
    mustChangePassword = _value;
    return mustChangePassword;
}

/// <summary>
/// Every warehouse this worker may work in, with exactly one flagged default.
///
/// The app signs them into the default and offers the rest as a switch. A worker cannot pick
/// a warehouse that is not on this list, which is the point: the free-text warehouse box in
/// settings was a typo away from an empty worklist that looked like a broken app.
/// </summary>
[DataMemberAttribute('Warehouses'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsWarehouseAssignment))]
public List parmWarehouses(List _value = warehouses)
{
    warehouses = _value;
    return warehouses;
}

/// <summary>
/// Set only on an otherwise-successful sign-in (Success = true) when the app's license expires
/// within HSMobileOpsUserService's renewal-warning window - blank the rest of the time. Never
/// blocks the sign-in itself, unlike every ErrorCode on this contract; the app shows it as a
/// dismissible notice, not a rejection.
/// </summary>
[DataMemberAttribute('LicenseWarning')]
public str parmLicenseWarning(str _value = licenseWarning)
{
    licenseWarning = _value;
    return licenseWarning;
}

/// <summary>
/// Every module this worker has been explicitly touched for, in either direction. Empty for
/// every worker an admin has never touched - which means every module stays allowed, not
/// that none do. See HSMobileOpsUserModulePermission's class doc for the absence-means-
/// allowed rule this list depends on, and the app's own ModulePermissionDto for the same
/// note on the receiving end.
/// </summary>
[DataMemberAttribute('ModulePermissions'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsModulePermission))]
public List parmModulePermissions(List _value = modulePermissions)
{
    modulePermissions = _value;
    return modulePermissions;
}
